// GUARD (defense-in-depth on top of the read-only DB role): force a single read-only SELECT and
// cap the result size. Anything that is not a lone SELECT/WITH becomes a harmless SELECT that just
// returns an instruction row - so the agent gets a clear message back instead of an execution error.
const raw = ($json.sql != null ? $json.sql : '');
let sql = String(raw).trim().replace(/;+\s*$/, '').trim();
// Small models occasionally drop the underscore in identifiers (pipelinedocuments). Repair the known
// table names so a correct-but-misspelled query still runs instead of erroring with 'relation does not exist'.
sql = sql.replace(/\bpipelinedocuments\b/gi, 'pipeline_documents').replace(/\bpipelineaudit\b/gi, 'pipeline_audit');
const ok = /^(select|with)\b/i.test(sql) && !sql.includes(';');
if (!ok) {
  sql = "SELECT 'Only a single read-only SELECT statement is allowed. Rewrite your query as one SELECT.' AS error";
} else if (!/\blimit\s+\d+/i.test(sql)) {
  sql = sql + ' LIMIT 100';
}
return [{ json: { sql, viaWebhook: $json.viaWebhook } }];

// Collect the returned rows into one compact object for the agent (or the webhook caller).
// alwaysOutputData means an empty result still yields one item; drop empty items so rowCount is honest.
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
return [{ json: { rowCount: rows.length, rows, viaWebhook: $('Normalize').first().json.viaWebhook } }];
